; flip.asm -- chapter 13: a table of every byte turned round
; generated by gen13.py
        INCLUDE "msx.inc"
        OUTPUT "flip.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
MIRRORS EQU $D000               ; the table, a whole page of the RAM
ONE     EQU $C200               ; 32 bytes turned round by mirror
TWO     EQU $C220               ; the same 32, turned round by the table
; A table of every byte with its bits in the opposite order, made once with
; chapter 10's mirror; then 32 bytes turned round by mirror and the same 32
; turned round by the table.
init:   di
        ld sp, SYS_AREA
        ld hl, sprite
        ld de, ONE
        ld bc, 32
        ldir
        ld hl, sprite
        ld de, TWO
        ld bc, 32
        ldir                    ; the 32 bytes, twice, into the RAM
t0:     call mktab              ; the table, made once
t1:     ld de, ONE
        ld b, 32
t2:     call byrout             ; 32 bytes, with mirror
t3:     ld de, TWO
        ld b, 32
t4:     call bytab              ; the same 32, with the table
t5:     nop
stop:   jr stop

; mktab: the 256-byte table at $D000: byte n holds n mirrored
mktab:  ld hl, MIRRORS
mk1:    ld a, l                 ; n
        call mirror
        ld (hl), a
        inc l
        jr nz, mk1              ; L back round to 0: all 256 done
        ret

; byrout: the B bytes at DE turned round, each by a call of mirror
byrout: ld a, (de)
        push bc                 ; mirror uses B and C
        call mirror
        pop bc
        ld (de), a
        inc de
        djnz byrout
        ret

; bytab: the B bytes at DE turned round with the table
bytab:  ld h, high MIRRORS      ; H: the table's page
bt1:    ld a, (de)
        ld l, a                 ; L: the byte, so HL points at its answer
        ld a, (hl)
        ld (de), a
        inc de
        djnz bt1
        ret

; mirror: A = A with its bits in the opposite order. Uses B and C.
;         (chapter 10)
mirror: ld c, a
        ld b, 8
mr1:    rr c
        rla
        djnz mr1
        ret

sprite: db $01, $03, $07, $0F, $1F, $3F, $7F, $FF, $80, $C0, $E0, $F0, $F8, $FC, $FE, $FF, $18, $3C, $7E, $FF, $FF, $7E, $3C, $18, $AA, $55, $AA, $55, $0F, $F0, $33, $CC
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
